SELECT percentile_cont(0.75) within GROUP (ORDER BY MAX(value)) FROM labevents JOIN patients ON labevents.subject_id = patients.subject_id JOIN admissions ON labevents.subject_id = admissions.subject_id WHERE patients.gender = 'M' AND EXISTS (SELECT 1 FROM diagnoses_icd WHERE diagnoses_icd.subject_id = labevents.subject_id AND diagnoses_icd.icd_code = 'ACS') AND EXTRACT(YEAR FROM age(CURRENT_DATE, patients.dob)) = 64;